// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: caller address and proposed unlock time and an ether amount
    function testFuzz_property(address caller, uint256 proposedUnlockTime, uint256 amount) public {
        // keep amount in a reasonable range and non-zero so Put is meaningful
        amount = bound(amount, 0, 5 ether);
        // ensure caller is non-zero
        if (caller == address(0)) caller = address(1);

        // fund caller so they can send amount
        vm.deal(caller, amount);

        // perform the Put from caller with fuzzed proposedUnlockTime and amount
        vm.prank(caller);
        bool ok;
        try c.Put{value: amount}(proposedUnlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for the correct contract, after a successful Put call,
        // Acc[caller].unlockTime is >= current block.timestamp. We assert that when Put returned successfully.
        // This will hold for the reference implementation for all inputs, and the mutant that sets unlockTime = _unlockTime
        // can violate it (i.e., produce unlockTime < block.timestamp) for some fuzzed proposedUnlockTime values.
        if (ok) {
            (uint256 gotUnlockTime, ) = c.Acc(caller);
            assertTrue(gotUnlockTime >= block.timestamp);
        } else {
            // if Put reverted, we still must satisfy the universal property vacuously; do nothing
            assertTrue(true);
        }
    }
}

