pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: actor (who calls Put) and the candidate unlock time.
    // The property: after Put is called, Acc[actor].unlockTime >= block.timestamp for the correct contract.
    function testFuzz_property(address actor, uint256 _unlockTime) public {
        // Keep actor non-zero and distinct from address(0)
        vm.assume(actor != address(0));

        // Give the actor some ETH to send with Put; keep amount small but >0 to satisfy MinSum logic if needed
        uint256 sendAmt = 1 ether; // use a constant amount to fund the call; fuzz focuses on actor and _unlockTime
        vm.deal(actor, sendAmt);

        // Ensure we call as actor
        vm.prank(actor);
        // Call Put with value
        c.Put{value: sendAmt}(_unlockTime);

        // Exactly one assertion: the reference guarantees acc.unlockTime >= block.timestamp for all inputs
        // Read the public mapping getter Acc(actor).unlockTime via the autogenerated accessor
        // Note: Acc is public mapping to Holder struct; solidity generates Acc(address) -> (unlockTime,balance)
        (uint256 unlockTime, ) = c.Acc(actor);
        assertTrue(unlockTime >= block.timestamp);
    }
}

