    function testFuzz_property(address actor, uint256 unlockTime) public {
        // keep actor non-zero and not this (though not strictly necessary); wide domain
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // give actor some ether to send
        uint256 sendAmt = 1 ether;
        vm.deal(actor, sendAmt);

        // ensure block.timestamp is some value; let it be current
        uint256 before = block.timestamp;

        // have actor call Put with fuzzed unlockTime and 1 ether
        vm.prank(actor);
        c.Put{value: sendAmt}(unlockTime);

        // Read the stored unlockTime for actor from the contract's public mapping getter
        uint256 recordedUnlock = c.Acc(actor).unlockTime;

        // General rule: in the reference C, after Put any acc.unlockTime >= block.timestamp
        // (it clamps to now). We assert that property by checking recordedUnlock >= before.
        // This holds for all inputs on the reference and is violated by the mutant when
        // unlockTime < block.timestamp.
        assertTrue(recordedUnlock >= before);
    }
}

