pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint256 unlockTime, uint256 value) public {
        // keep values sensible but wide
        vm.assume(actor != address(0));
        // cap value so vm.deal doesn't overflow and so sending is feasible
        value = bound(value, 0, 10 ether);
        // fund actor
        vm.deal(actor, value);
        // perform call as actor to Put(unlockTime) with value
        vm.prank(actor);
        // use try/catch to ensure we capture whether Put reverts; reference does not revert here
        bool ok;
        try c.Put{value: value}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference guarantees that after a successful Put call, Acc[actor].unlockTime >= block.timestamp.
        // We assert that either the call reverted (ok == false) or the stored unlockTime is >= block.timestamp.
        // The reference never stores a past unlockTime on success, but the mutant can, causing this assertion to fail for some inputs.
        uint storedUnlock = c.Acc(actor).unlockTime;
        assertTrue(!ok || storedUnlock >= block.timestamp);
    }
}

