        uint256 arg = bound(unlockArg, 0, type(uint256).max);

        // fund actor so they can send ETH with the call
        vm.deal(actor, 1 ether);

        // record block timestamp before the call
        uint256 before = block.timestamp;

        // perform the Put call as the actor, sending some value
