        // The universal property: after Put returns, unlockTime must be >= block.timestamp_at_call (before)
        // This is true for the reference implementation for all admissible inputs; the mutant (which treats
        // the argument as a duration) can violate it for some inputs, so the fuzz should find such cases
        // against the mutant while this passes on the reference.
        assertTrue(unlockTime >= before);
    }

    // helper to read the public struct mapping via the autogenerated getter
    function getHolder(address a) internal view returns (uint256 unlockTime, uint256 balance) {
        // The autogenerated getter for mapping (address => Holder) public Acc returns (uint, uint)
        (unlockTime, balance) = c.Acc(a);
