pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: caller address and desired unlockTime and deposit amount
    function testFuzz_property(address caller, uint256 unlockTime, uint256 deposit) public {
        // keep deposit within reasonable bounds and non-zero to exercise balance change
        deposit = bound(deposit, 1 wei, 10 ether);
        // avoid zero address as caller to keep semantics realistic
        vm.assume(caller != address(0));

        // fund caller and perform Put as caller sending deposit with provided unlockTime
        vm.deal(caller, deposit);
        vm.prank(caller);
        bool ok;
        // call Put and capture success (should not revert)
        try c.Put{value: deposit}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful Put on the correct contract, the invariant holds:
        // Acc[caller].unlockTime == max(unlockTime, block.timestamp_at_call)
        // We can only observe current block.timestamp. Since Put used block.timestamp at execution,
        // and no time warp is done between call and assertion, the expected unlockTime is max(unlockTime, block.timestamp).
        // If the call reverted, we cannot assume state changed; in that case ok==false and we still assert ok implies the property.

        // Build expected value
        uint256 expected = unlockTime > block.timestamp ? unlockTime : block.timestamp;

        // Single property assertion reading c's public getter Acc(caller).unlockTime
        // The assertion: if the Put call succeeded, then c.Acc(caller).unlockTime equals expected.
        // This is a universal rule the reference satisfies; the mutant that omits the assignment will fail for some inputs.
        if (ok) {
            (, uint256 bal) = c.Acc(caller);
            // read unlockTime via the public getter Acc
            // Acc getter returns (uint256 unlockTime, uint256 balance) due to struct public
            // However solidity auto-generated getter order is (uint256 unlockTime, uint256 balance)
            // We call it and assert the unlockTime matches expected.
            // Note: We already captured bal to align with return tuple ordering.
            (uint256 gotUnlockTime, ) = c.Acc(caller);
            assertTrue(gotUnlockTime == expected);
        } else {
            // If the call reverted, the reference contract also might revert for invalid inputs;
            // in that case we assert that it indeed reverted (ok == false) while not making any state assertion.
            // To satisfy the single-assert rule, assertTrue(!ok);
            // But to ensure the test is meaningful we only assertTrue(!ok) when Put reverted.
            assertTrue(!ok);
        }
    }
}

