pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint256 sendAmount, uint256 futureOffset) public {
        // keep actor non-zero and sendAmount within reasonable bounds
        vm.assume(actor != address(0));
        // bound sendAmount to a small max so vm.deal is reasonable; keep wide
        sendAmount = bound(sendAmount, 1 wei, 10 ether);
        // futureOffset is the amount of seconds in future for unlock; allow 1..1e9
        futureOffset = bound(futureOffset, 1, 1e9);

        // decide a future unlock time relative to current block.timestamp
        uint256 suppliedUnlock = block.timestamp + futureOffset;

        // fund the actor and perform Put as that actor
        vm.deal(actor, sendAmount);
        vm.prank(actor);
        // call Put with a future unlock time
        c.Put{value: sendAmount}(suppliedUnlock);

        // Read the stored unlockTime for actor via the public mapping getter
        (uint256 storedUnlock,,) = (c.Acc(actor).unlockTime, c.Acc(actor).balance, 0);
        // The general rule: if caller supplied a strictly future unlock time, the contract must record an unlockTime
        // that is at least the supplied value (i.e., it preserves future intent). The buggy mutant that always sets
        // block.timestamp would record storedUnlock == block.timestamp, which is < suppliedUnlock for any positive futureOffset.
        assertTrue(storedUnlock >= suppliedUnlock);
    }
}

