    // depositAmount - amount (wei) to deposit into c via Put (must be >= c.MinSum())
    // unlockTime - a future timestamp to set as unlockTime when depositing
    // collectAmount - amount to attempt to collect (<= depositAmount)
    function run(address depositor, uint depositAmount, uint unlockTime, uint collectAmount) public payable {
        // Preconditions for meaningful scenario
        require(depositAmount >= collectAmount, "deposit >= collect");
        require(depositAmount >= c.MinSum(), "deposit >= MinSum");
        require(unlockTime >= block.timestamp, "unlock in future or now");

