        c.Put{value: depositAmount}(unlockTime);

        // Fast-forward not possible; instead we use the actual block.timestamp.
        // We want to test behavior at exactly unlockTime. If unlockTime > block.timestamp, we cannot move time,
        // so require that unlockTime equals current block.timestamp (or was set to block.timestamp by Put when passing 0).
        // To keep general, require unlockTime == block.timestamp.
        require(unlockTime == block.timestamp, "unlockTime must equal current block.timestamp for this test");

