        uint balBefore = c.Acc(depositor).balance;

        // Attempt collect of collectAmount
        c.Collect(collectAmount);

        // Observe balance after collect
        uint balAfter = c.Acc(depositor).balance;

        // Property: at timestamp equal to unlockTime, the holder's balance must NOT decrease (i.e., no collect allowed at exact time)
        assert(balAfter + collectAmount <= balBefore);
    }

    // Allow this test contract to receive ETH for forwarding deposits
    receive() external payable {}
}

