contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract so that Collect will attempt to send out am and succeed/fail depending on transfer method.
    // We require the caller to fund this test contract beforehand so it can Put into c and then Collect.
    function run(uint unlockDelay, uint putAmount, uint am) public {
        // Preconditions to make Collect's if-condition pass: putAmount >= c.MinSum() and putAmount >= am
        require(putAmount >= am, "putAmount must cover am");
        require(putAmount >= c.MinSum(), "putAmount must be >= MinSum");

        // Ensure this contract has enough ETH to put into c
        require(address(this).balance >= putAmount, "not enough ETH for putAmount");

        // Record old balance of c
        uint oldBal = address(c).balance;

        // Deposit into c with unlock time in the past + unlockDelay to set unlockTime <= now + unlockDelay
        uint unlockTime = block.timestamp + unlockDelay;
        c.Put{value: putAmount}(unlockTime);

        // Advance time is not possible here; ensure unlockDelay is 0 so Collect can proceed immediately
        require(unlockDelay == 0, "unlockDelay must be 0 to allow immediate Collect");

        // Now call Collect to withdraw 'am'
        c.Collect(am);

        // After Collect, c's balance must have decreased exactly by am
        assert(address(c).balance == oldBal + putAmount - am);
    }

    // Allow the test contract to receive ethers so caller can fund it before calling run
    receive() external payable {}
}

